import { DESKTOP_COLS_NUMBER, DESKTOP_PATTERN, DESKTOP_PREFIX, DESKTOP_START_PATTERN, DESKTOP_START_PREFIX, GRID_COL_PATTERN, GRID_COL_PREFIX, GRID_COL_START_PATTERN, GRID_COL_START_PREFIX, MOBILE_COLS_NUMBER, MOBILE_PATTERN, MOBILE_PREFIX, MOBILE_START_PATTERN, MOBILE_START_PREFIX, TABLET_COLS_NUMBER, TABLET_PATTERN, TABLET_PREFIX, TABLET_START_PATTERN, TABLET_START_PREFIX } from "./constants";
// eslint-disable-next-line complexity
export const updateGridStateFromClassNames = (gridState, item) => {
    const { className } = item.props;
    if (!className) {
        return;
    }
    const gridColClassesLast = className.split(" ").filter((el) => el.match(GRID_COL_PATTERN)).reverse()[0] || "";
    const desktopClassesLast = className.split(" ").filter((el) => el.match(DESKTOP_PATTERN)).reverse()[0] || "";
    const tabletClassesLast = className.split(" ").filter((el) => el.match(TABLET_PATTERN)).reverse()[0] || "";
    const mobileClassesLast = className.split(" ").filter((el) => el.match(MOBILE_PATTERN)).reverse()[0] || "";
    const gridColClassesStartLast = className.split(" ").filter((el) => el.match(GRID_COL_START_PATTERN)).reverse()[0] || "";
    const desktopStartClassesLast = className.split(" ").filter((el) => el.match(DESKTOP_START_PATTERN)).reverse()[0] || "";
    const tabletStartClassesLast = className.split(" ").filter((el) => el.match(TABLET_START_PATTERN)).reverse()[0] || "";
    const mobileStartClassesLast = className.split(" ").filter((el) => el.match(MOBILE_START_PATTERN)).reverse()[0] || "";
    const gridColValue = Number(gridColClassesLast.split(GRID_COL_PREFIX)[1]);
    const lg = Number(desktopClassesLast.split(DESKTOP_PREFIX)[1]);
    const md = Number(tabletClassesLast.split(TABLET_PREFIX)[1]);
    const sm = Number(mobileClassesLast.split(MOBILE_PREFIX)[1]);
    const gridColStartValue = Number(gridColClassesStartLast.split(GRID_COL_START_PREFIX)[1]);
    const lgStart = Number(desktopStartClassesLast.split(DESKTOP_START_PREFIX)[1]);
    const mdStart = Number(tabletStartClassesLast.split(TABLET_START_PREFIX)[1]);
    const smStart = Number(mobileStartClassesLast.split(MOBILE_START_PREFIX)[1]);
    if (gridColValue && gridColValue > 0) {
        gridState.gridLg = gridColValue > DESKTOP_COLS_NUMBER ? DESKTOP_COLS_NUMBER : gridColValue;
        gridState.gridMd = gridColValue > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : gridColValue;
        gridState.gridSm = gridColValue > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : gridColValue;
    }
    if (lg && lg > 0) {
        gridState.lg = lg > DESKTOP_COLS_NUMBER ? DESKTOP_COLS_NUMBER : lg;
    }
    if (md && md > 0) {
        gridState.md = md > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : md;
    }
    if (sm && sm > 0) {
        gridState.sm = sm > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : sm;
    }
    if (gridColStartValue && gridColStartValue > 0) {
        gridState.gridLgStart = gridColStartValue > DESKTOP_COLS_NUMBER ? DESKTOP_COLS_NUMBER : gridColStartValue;
        gridState.gridMdStart = gridColStartValue > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : gridColStartValue;
        gridState.gridSmStart = gridColStartValue > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : gridColStartValue;
    }
    if (lgStart && lgStart > 0) {
        gridState.lgStart = lgStart > DESKTOP_COLS_NUMBER ? DESKTOP_COLS_NUMBER : lgStart;
    }
    if (mdStart && mdStart > 0) {
        gridState.mdStart = mdStart > TABLET_COLS_NUMBER ? TABLET_COLS_NUMBER : mdStart;
    }
    if (smStart && smStart > 0) {
        gridState.smStart = smStart > MOBILE_COLS_NUMBER ? MOBILE_COLS_NUMBER : smStart;
    }
};
